def get_vdu_mrbts_name_by_restapi(conn_alias='default'):
    return vdu_ope_base.get_vdu_mrbts_id_from_webem(conn_alias=conn_alias)


def get_vdu_sw_release(conn_alias='default'):
    sw_version = vdu_ope_base.get_vdu_sw_version_from_webem(conn_alias=conn_alias)
    # "vDUCNF23R2_0.300.946119"
    release = re.search("\\S*(\\d{2}R\\d{1})", sw_version).group(1)
    return release


def get_vdu_sw_stream(conn_alias='default'):
    sw_version = vdu_ope_base.get_vdu_sw_version_from_webem(conn_alias=conn_alias)
    # "vDUCNF23R2_0.300.946119"
    stream = re.search("\\d\\d\\w\\d", sw_version).group(0)
    # release = re.search("\\S*(\\d{2}R\\d{1})", sw_version).group(1)
    return stream


def all_vdu_cells_status_should_be_normal(conn_alias='default'):
    """
    checking all of the cells under one vdu should be onair.

    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return: None
    """
    cells_info = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    for cell in cells_info:
        if cell['administrative_state'] != 'Unlocked':
            raise AssertionError('The admin state of {cell_name} is {admin_state}'.format(cell_name=cell['name'],
                                                                                          admin_state=cell[
                                                                                              'administrative_state']))
        if cell['operational_state'] != 'enabled':
            raise AssertionError('The operational state of {} is {}'.format(cell['name'], cell['operational_state']))
        if cell['blocking_state'] != 'Unblocked':
            raise AssertionError('The blocking state of {} is {}'.format(cell['name'], cell['blocking_state']))
        if cell['availability_status'] != 'on line':
            raise AssertionError('The availability state of {} is {}'.format(cell['name'], cell['availability_status']))

    logger.info('{} All of the cells statuses are normal {}'.format(LOG_HEAD, LOG_END))


def checking_pod_as_expected(pod_info, key, expected_result):
    error_pod = []
    for pod in pod_info:
        if pod_info[pod][key] != expected_result:
            logger.info('The {key} of {pod} is {result}'.format(pod=pod,
                                                                key=key,
                                                                result=pod_info[pod][key]))
            error_pod.append(pod)
    if error_pod:
        raise AssertionError('{pod} are not as expected:{result}'.format(pod=error_pod,
                                                                         result=expected_result))


def get_cell_ssbarfch(cell_index, conn_alias='default'):
    cell_status = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    for cell_state in cell_status:
        if cell_state['name'] == 'NRCELL-' + cell_index:
            dist_name = cell_state['dist_names']['config']
    ssb_arfcn = vdu_cm_base.get_parameter_value_from_current_plan(mo_dn=dist_name,
                                                                  parameter_name='arfcnSsbPbch',
                                                                  conn_alias=conn_alias)
    return ssb_arfcn


def get_cell_pci(cell_index, conn_alias='default'):
    cell_status = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    for cell_state in cell_status:
        if cell_state['name'] == 'NRCELL-' + cell_index:
            dist_name = cell_state['dist_names']['config']
    pci = vdu_cm_base.get_parameter_value_from_current_plan(mo_dn=dist_name,
                                                            parameter_name='physCellId',
                                                            conn_alias=conn_alias)
    return pci


def get_cell_attribute(attr_name, cell_index, conn_alias='default'):
    cell_status = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    for cell_state in cell_status:
        if cell_state['name'] == 'NRCELL-' + cell_index:
            value = cell_state[attr_name]
            return value


def get_cell_list_from_webem(conn_alias='default'):
    cell_list = []
    cell_status = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    for cell_state in cell_status:
        cell_index = cell_state['name'].lstrip('NRCELL-')
        cell_list.append(cell_index)
    return cell_list


def get_vdu_all_cells_status(conn_alias='default'):
    cells_info = vdu_ope_base.get_all_vdu_cells_statuses(conn_alias=conn_alias)
    return cells_info


def vdu_cells_status_should_be_as_expected(cell_id, cells_info, log_level='DEBUG', **kwargs):
    unexpected = False
    for cell_info in cells_info:
        if cell_id == cell_info['id']:
            for key, value in kwargs.items():
                try:
                    if cell_info[key] != value:
                        raise AssertionError(
                            '{log_head} The {state} of {cell_name} is {status} {log_end}'.format(log_head=LOG_HEAD,
                                                                                                 state=key,
                                                                                                 cell_name=cell_info['name'],
                                                                                                 status=cell_info[key],
                                                                                                 log_end=LOG_END))
                except AssertionError as e:
                    if log_level == 'ERROR':
                        logger.error(str(e))
                    else:
                        logger.debug(str(e))
                    unexpected = True
                    continue
    return unexpected


def pod_container_number_should_be_equal(pod_info):
    for key, pod in enumerate(pod_info):
        info = pod_info.get(pod)
        ready = info['ready']
        if ready.split('/')[0] != ready.split('/')[1]:
            raise AssertionError('pod {pod} container number not equal'.format(pod=pod))
